begin read only;set local search_path='';with targets as(select c.oid,n.nspname||'.'||c.relname name,c.relowner,c.relacl,c.relrowsecurity,c.relforcerowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in('billing_provider_events','billing_entitlement_applications','billing_settlement_outcomes','billing_orders','billing_payment_attempts','billing_subscriptions','billing_plan_versions')), t as(select name,pg_get_userbyid(relowner) owner,relrowsecurity rls,relforcerowsecurity force_rls,(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=targets.oid and a.attnum>0 and not a.attisdropped) columns,(select jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated) order by c.conname) from pg_constraint c where c.conrelid=targets.oid) constraints,(select jsonb_agg(jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'constraint_owned',exists(select 1 from pg_constraint k where k.conindid=i.indexrelid)) order by i.indexrelid::regclass::text) from pg_index i where i.indrelid=targets.oid) indexes,(select jsonb_agg(jsonb_build_object('name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid),'function',tgfoid::regprocedure::text,'function_md5',(select md5(replace(prosrc,chr(13),'')) from pg_proc where oid=tgfoid)) order by tgname) from pg_trigger where tgrelid=targets.oid and not tgisinternal) triggers,(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by a.grantee::regrole::text,a.privilege_type) from aclexplode(coalesce(relacl,acldefault('r',relowner))) a) acl,(select jsonb_agg(jsonb_build_object('column',a.attname,'role',case when g.grantee=0 then 'PUBLIC' else pg_get_userbyid(g.grantee) end,'privilege',g.privilege_type,'grantable',g.is_grantable) order by a.attname,g.grantee::regrole::text,g.privilege_type) from pg_attribute a cross join lateral aclexplode(a.attacl) g where a.attrelid=targets.oid) column_acl,(select jsonb_agg(jsonb_build_object('name',p.polname,'permissive',p.polpermissive,'cmd',p.polcmd,'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end order by r::regrole::text) from unnest(p.polroles) r),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by polname) from pg_policy p where p.polrelid=targets.oid) policies from targets),f as(select p.oid::regprocedure::text signature,pg_get_userbyid(proowner) owner,md5(replace(prosrc,chr(13),'')) body_md5,prosecdef,proconfig,provolatile,(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by a.grantee::regrole::text,a.privilege_type) from aclexplode(coalesce(proacl,acldefault('f',proowner))) a) acl from pg_proc p where p.oid in(to_regprocedure('private.billing_orders_immutability()'),to_regprocedure('public.billing_settle_paymob_hmac_verified(jsonb)'),to_regprocedure('public.billing_create_or_reuse_subscription_order(uuid,text,text,uuid,uuid,text,text,text,bigint,text,integer,text,integer,text,text,uuid)'),to_regprocedure('private.billing_settle_payment_core(jsonb)'))) select jsonb_build_object('project','vmpifljyozsbtssxhoxd','tables',(select jsonb_agg(to_jsonb(t) order by name) from t),'functions',(select jsonb_agg(to_jsonb(f) order by signature) from f)) metadata;commit;
